    name: {
      de: "Laos Büffelfarm",
      hu: "Laoszi Bivalyfarm",
      ro: "Ferma de Bivoli din Laos",
      en: "Laos Buffalo Dairy"},
    image: "/poi-images/laos-buffalo-dairy-life-v2.webp",
    description: {
      de: "Eine sozial verantwortliche Farm, die Käse, Eiscreme und Joghurt aus der Milch lokaler Wasserbüffel herstellt.",
      hu: "Társadalmilag felelős farm, amely sajtot, jégkrémet és joghurtot készít a helyi vízibivalyok tejéből.",
      ro: "O fermă responsabilă social care produce brânză, înghețată și iaurt din laptele bivolilor de apă locali.",
      en: "A socially responsible farm that produces cheese, ice cream, and yogurt from the milk of local water buffaloes.",
      es: "Una granja socialmente responsable que produce queso, helado y yogur de la leche de búfalos de agua locales.",
      pt: "Uma quinta socialmente responsável que produz queijo, gelado e iogurte a partir do leite de búfalos de água locais.",
      fr: "Une ferme socialement responsable produisant du fromage, de la glace et du yaourt à partir du lait de buffles d'eau locaux.",
    },
    facts: {
      de: ["Hilft lokalen Bauern.", "Erste Büffelfarm in Laos.", "Produziert frischen Käse.", "Bietet interaktive Touren."],
      hu: ["Segíti a helyi gazdákat.", "Az első bivalyfarm Laoszban.", "Friss sajtot állít elő.", "Interaktív túrákat kínál."],
      ro: ["Ajută fermierii locali.", "Prima fermă de bivoli din Laos.", "Produce brânză proaspătă.", "Oferă tururi interactive."],
      en: ["Helps local farmers.", "First buffalo dairy in Laos.", "Produces fresh cheese.", "Offers interactive tours."],
      es: ["Ayuda a agricultores locales.", "Primera granja de búfalos en Laos.", "Produce queso fresco.", "Ofrece recorridos interactivos."],
      pt: ["Ajuda os agricultores locais.", "Primeira quinta de búfalos no Laos.", "Produz queijo fresco.", "Oferece visitas interativas."],
      fr: ["Aide les agriculteurs locaux.", "Première ferme de buffles au Laos.", "Produit du fromage frais.", "Propose des visites interactives."],
    }, image: "/poi-images/laos-buffalo-dairy-life-v2.webp",
    descriptionAdvanced: {
      de: "Die Laos Buffalo Dairy in der Nähe von Luang Prabang ist das erste kommerzielle Büffelmilch-Unternehmen des Landes. Die Farm verfolgt ein innovatives soziales Geschäftsmodell, bei dem Wasserbüffel von lokalen Bauern gemietet werden, um ihnen ein regelmäßiges Zusatzeinkommen zu sichern. Während der Mietzeit erhalten die Tiere tierärztliche Betreuung, Impfungen und hochwertiges Futter, was ihre allgemeine Gesundheit erheblich verbessert. Aus der gewonnenen Büffelmilch werden Käse, Joghurt und Eiscreme produziert, die an Hotels und Restaurants verkauft werden. Die Farm dient auch als Ausbildungszentrum für die lokale Bevölkerung, um Wissen über Tierhaltung und landwirtschaftliche Praktiken zu vermitteln. Das Projekt trägt dazu bei, die Unterernährung bei Kindern in ländlichen Gebieten durch Aufklärungskampagnen zu reduzieren.",
      hu: "A Luang Prabang közelében található Laos Buffalo Dairy az ország első kereskedelmi bivalytej-üzeme. A farm innovatív társadalmi üzleti modellt követ, amelynek során vízibivalyokat bérelnek a helyi gazdáktól, így biztosítva számukra rendszeres kiegészítő jövedelmet. A bérleti időszak alatt az állatok állatorvosi ellátást, védőoltásokat és kiváló minőségű takarmányt kapnak, ami jelentősen javítja általános egészségi állapotukat. A kinyert bivalytejből sajtot, joghurtot és jégkrémet készítenek, amelyeket szállodáknak és éttermeknek értékesítenek. A farm oktatóközpontként is szolgál a helyi lakosság számára, ahol az állattartással és mezőgazdasági gyakorlatokkal kapcsolatos ismereteket adják át. A projekt tájékoztató kampányokkal is segít csökkenteni a vidéki területeken a gyermekek alultápláltságát.",
      ro: "Laos Buffalo Dairy, situată lângă Luang Prabang, este prima companie comercială de lapte de bivoliță din țară. Ferma urmează un model de afaceri social inovator, în care bivolii de apă sunt închiriați de la fermierii locali pentru a le oferi un venit suplimentar regulat. Pe parcursul perioadei de închiriere, animalele primesc îngrijire veterinară, vaccinări și furaje de înaltă calitate, ceea ce le îmbunătățește considerabil starea generală de sănătate. Din laptele obținut se produc brânzeturi, iaurt și înghețată, care sunt vândute hotelurilor și restaurantelor. Ferma servește și ca centru de formare pentru populația locală, diseminând cunoștințe despre creșterea animalelor și practicile agricole. Proiectul contribuie, de asemenea, la reducerea malnutriției în rândul copiilor din zonele rurale.",
      en: "The Laos Buffalo Dairy near Luang Prabang is the first commercial buffalo milk enterprise in the country. The farm pursues an innovative social business model in which water buffaloes are rented from local farmers to provide them with a regular additional income. During the rental period, the animals receive veterinary care, vaccinations, and high-quality feed, which significantly improves their overall health. The extracted buffalo milk is used to produce cheese, yogurt, and ice cream, which are sold to hotels and restaurants. The farm also serves as a training center for the local population to impart knowledge about animal husbandry and agricultural practices. The project also helps to reduce child malnutrition in rural areas through educational campaigns.",
      es: "La Laos Buffalo Dairy, cerca de Luang Prabang, es la primera empresa comercial de leche de búfala del país. La granja sigue un modelo de negocio social innovador en el que se alquilan búfalos de agua a agricultores locales para asegurarles ingresos adicionales regulares. Durante el periodo de alquiler, los animales reciben atención veterinaria, vacunas y alimento de alta calidad, lo que mejora significativamente su salud general. Con la leche obtenida se producen quesos, yogures y helados que se venden a hoteles y restaurantes. La granja también funciona como centro de formación para la población local, transmitiendo conocimientos sobre ganadería y prácticas agrícolas. El proyecto ayuda a reducir la desnutrición infantil en áreas rurales mediante campañas educativas.",
      pt: "A Laos Buffalo Dairy, perto de Luang Prabang, é a primeira empresa comercial de leite de búfala do país. A quinta segue um modelo de negócio social inovador, no qual os búfalos de água são alugados a agricultores locais para lhes garantir um rendimento extra regular. Durante o período de aluguer, os animais recebem cuidados veterinários, vacinas e ração de alta qualidade, o que melhora significativamente a sua saúde geral. O leite de búfala obtido é utilizado para produzir queijo, iogurte e gelado, que são vendidos a hotéis e restaurantes. A quinta serve também como centro de formação para a população local, transmitindo conhecimentos sobre pecuária e práticas agrícolas. O projeto contribui para reduzir a subnutrição infantil em áreas rurais através de campanhas educativas.",
      fr: "La Laos Buffalo Dairy, près de Luang Prabang, est la première entreprise commerciale de lait de bufflonne du pays. La ferme suit un modèle commercial social innovant où les buffles d'eau sont loués aux agriculteurs locaux pour leur assurer un revenu supplémentaire régulier. Pendant la période de location, les animaux reçoivent des soins vétérinaires, des vaccins et une alimentation de qualité, ce qui améliore considérablement leur santé. Le lait obtenu est transformé en fromage, yaourt et glace, vendus aux hôtels et restaurants. La ferme sert également de centre de formation pour la population locale afin de transmettre des connaissances sur l'élevage et les pratiques agricoles. Le projet contribue à réduire la malnutrition infantile dans les zones rurales grâce à des campagnes d'éducation.",
    },
