      fr: ["Pionnière de l'agriculture biologique au Laos", "Cultive des mûriers pour la production de thé", "Produit du fromage de chèvre maison", "Renonce complètement aux pesticides chimiques", "Propose des cours de lutte naturelle contre les nuisibles", "Utilise les revenus pour des projets scolaires locaux"],
