      ro: ["Salvează foști elefanți de lucru", "Oferă animalelor o pensionare sigură", "Renunță complet la călăritul elefanților", "Sprijină familiile locale de mahouți", "Vizitatorii se pot scălda cu elefanții în râu", "Promovează turismul etic cu animale"],
      en: ["Rescues former working elephants", "Offers animals a safe retirement", "Completely refrains from elephant riding", "Supports local mahout families", "Visitors can bathe with elephants in the river", "Promotes ethical animal tourism"],
      es: ["Rescata a antiguos elefantes de trabajo", "Ofrece a los animales un retiro seguro", "Renuncia por completo a montar a los elefantes", "Apoya a las familias de mahouts locales", "Los visitantes pueden bañarse con los elefantes en el río", "Promueve un turismo animal ético"],
      pt: ["Resgata antigos elefantes de trabalho", "Oferece aos animais uma reforma segura", "Prescinde completamente de montar elefantes", "Apoia as famílias de mahouts locais", "Os visitantes podem banhar-se com os elefantes no rio", "Promove um turismo animal ético"],
      fr: ["Sauve d'anciens éléphants de travail", "Offre aux animaux une retraite sûre", "Renonce complètement aux balades à dos d'éléphant", "Soutient les familles de cornacs locales", "Les visiteurs peuvent se baigner avec les éléphants dans la rivière", "Favorise un tourisme animalier éthique"],
