      es: ["Una de las zonas más inaccesibles de Laos", "Hogar del raro langur de patas rojas", "Incluye el lago de cráter volcánico Nong Fa", "Proporciona hábitat para leopardos asiáticos", "Una de las reservas menos exploradas", "Importante refugio para especies de aves en peligro"],
