      fr: ["L'une des zones les plus inaccessibles du Laos", "Refuge du rare douc à pattes rousses", "Comprend le lac de cratère volcanique Nong Fa", "Offre un habitat aux léopards d'Asie", "Compte parmi les réserves les moins explorées", "Refuge important pour les espèces d'oiseaux menacées"],
