      fr: ["Célèbre pour ses paysages karstiques gigantesques", "Borde les parcs nationaux vietnamiens", "Abrite la grotte de la rivière souterraine Xe-Bang-Fai", "Protège des espèces végétales endémiques dans les vallées karstiques", "Habitat du rare douc à pattes rousses", "La topographie empêche la déforestation à grande échelle"],
