      es: ["Cultiva especies de orquídeas laosianas amenazadas", "Opera un laboratorio in vitro para la propagación", "Colabora con botánicos internacionales", "Reintroduce plantas raras en la naturaleza", "Ofrece visitas guiadas educativas para turistas", "Cultiva también helechos tropicales"],
