    name: {
      de: "Nam Ha Naturschutzgebiet",
      hu: "Nam Ha Természetvédelmi Terület",
      ro: "Aria Protejată Nam Ha",
      en: "Nam Ha National Protected Area"},
    image: "/poi-images/nam-ha-protected-area-life-v2.webp",
    description: {
      de: "Ein weitläufiges Schutzgebiet, das berühmt für sein preisgekröntes Ökotourismus-Projekt und Trekking-Möglichkeiten im Dschungel ist.",
      hu: "Kiterjedt védett terület, amely díjnyertes ökoturisztikai projektjéről és dzsungeltúrázási lehetőségeiről híres.",
      ro: "O arie protejată extinsă, faimoasă pentru proiectul său premiat de ecoturism și oportunitățile de drumeții în junglă.",
      en: "An expansive protected area famous for its award-winning ecotourism project and jungle trekking opportunities.",
      es: "Una extensa área protegida famosa por su galardonado proyecto de ecoturismo y opciones de senderismo en la selva.",
      pt: "Uma área protegida extensa, famosa pelo seu premiado projeto de ecoturismo e oportunidades de trekking na selva.",
      fr: "Une vaste aire protégée célèbre pour son projet d'écotourisme primé et ses treks dans la jungle.",
    },
    facts: {
      de: ["ASEAN Heritage Park.", "Bietet Dschungeltrekking.", "Viele indigene Dörfer.", "Fokus auf Ökotourismus."],
      hu: ["ASEAN Örökség Park.", "Dzsungeltúrákat kínál.", "Sok bennszülött falu.", "Az ökoturizmusra fókuszál."],
      ro: ["Parc de Patrimoniu ASEAN.", "Oferă drumeții în junglă.", "Multe sate indigene.", "Accent pe ecoturism."],
      en: ["ASEAN Heritage Park.", "Offers jungle trekking.", "Many indigenous villages.", "Focus on ecotourism."],
      es: ["Parque del Patrimonio de la ASEAN.", "Senderismo en la selva.", "Muchas aldeas indígenas.", "Enfoque en ecoturismo."],
      pt: ["Parque Património da ASEAN.", "Oferece trekking na selva.", "Muitas aldeias indígenas.", "Foco no ecoturismo."],
      fr: ["Parc du patrimoine de l'ASEAN.", "Treks dans la jungle.", "Nombreux villages indigènes.", "Focus sur l'écotourisme."],
    }, image: "/poi-images/nam-ha-protected-area-life-v2.webp",
    descriptionAdvanced: {
      de: "Das nationale Schutzgebiet Nam Ha in der Provinz Luang Namtha ist ein Vorzeigeprojekt für gemeindebasierten Ökotourismus in Asien. Das Reservat schützt Bergwälder und Flusstäler, die eine hohe Dichte an Großsäugern wie Asiatische Elefanten und Nebelparder aufweisen. Zahlreiche Bergvölker, darunter die Akha und Lanten, leben innerhalb oder an den Grenzen des Parks und erhalten durch geführte Trekkingtouren eine alternative Einkommensquelle. Dieses Modell minimiert illegale Jagd und Abholzung erheblich. Die Flusslandschaften des Nam Ha River werden zudem für Kajak- und Raftingtouren genutzt, die tief in unberührte Naturgebiete führen. Wissenschaftler überwachen hier die Populationen seltener Amphibien und Vogelarten. Der Park zeigt eindrucksvoll, wie sich Naturschutz und indigene Entwicklung erfolgreich verbinden lassen.",
      hu: "A Luang Namtha tartományban található Nam Ha Nemzeti Védett Terület a közösségalapú ökoturizmus mintaprojektje Ázsiában. A rezervátum olyan hegyi erdőket és folyóvölgyeket véd, amelyekben nagy sűrűségben élnek olyan nagyemlősök, mint az ázsiai elefántok és a ködfoltos párducok. Számos hegyi nép, köztük az akha és lanten törzsek élnek a parkon belül vagy annak határain, és a vezetett túrák révén alternatív bevételi forráshoz jutnak. Ez a modell jelentősen minimalizálja az illegális vadászatot és a fakitermelést. A Nam Ha folyó tájait emellett kajakozásra és vadvízi evezésre is használják, amelyek mélyen bevezetnek az érintetlen természeti területekre. A tudósok itt figyelemmel kísérik a ritka kétéltűek és madárfajok populációit. A park lenyűgözően mutatja be, hogyan lehet sikeresen összekapcsolni a természetvédelmet és az őslakosok fejlődését.",
      ro: "Aria Națională Protejată Nam Ha din provincia Luang Namtha este un proiect pilot pentru ecoturismul bazat pe comunitate în Asia. Rezervația protejează pădurile montane și văile râurilor care au o densitate mare de mamifere mari, cum ar fi elefanții asiatici și leoparzii pătați. Numeroase triburi montane, inclusiv Akha și Lanten, trăiesc în interiorul sau la granițele parcului și primesc o sursă alternativă de venit prin excursii de drumeție ghidate. Acest model minimizează semnificativ vânătoarea ilegală și defrișările. Peisajele fluviale ale râului Nam Ha sunt, de asemenea, folosite pentru excursii cu caiacul și rafting, care duc adânc în zone naturale virgine. Oamenii de știință monitorizează populațiile de amfibieni și specii de păsări rare aici. Parcul demonstrează în mod impresionant modul în care conservarea naturii și dezvoltarea indigenă pot fi combinate cu succes.",
      en: "The Nam Ha National Protected Area in Luang Namtha province is a flagship project for community-based ecotourism in Asia. The reserve protects mountain forests and river valleys that have a high density of large mammals such as Asian elephants and clouded leopards. Numerous hill tribes, including the Akha and Lanten, live within or on the borders of the park and receive an alternative source of income through guided trekking tours. This model significantly minimizes illegal hunting and logging. The river landscapes of the Nam Ha River are also used for kayaking and rafting tours that lead deep into pristine natural areas. Scientists monitor the populations of rare amphibians and bird species here. The park impressively demonstrates how nature conservation and indigenous development can be successfully combined.",
      es: "El área protegida nacional Nam Ha, en la provincia de Luang Namtha, es un proyecto modelo de ecoturismo comunitario en Asia. La reserva protege bosques de montaña y valles fluviales que albergan una alta densidad de grandes mamíferos como elefantes asiáticos y panteras nebulosas. Numerosos pueblos de montaña, incluidos los Akha y Lanten, viven dentro o en los límites del parque y obtienen ingresos alternativos mediante caminatas guiadas. Este modelo minimiza significativamente la caza ilegal y la tala. Los paisajes fluviales del río Nam Ha también se utilizan para excursiones en kayak y balsa que llevan a zonas naturales vírgenes. Los científicos monitorean aquí las poblaciones de aves y anfibios raros. El parque demuestra cómo la conservación y el desarrollo indígena pueden unirse con éxito.",
      pt: "A área protegida nacional Nam Ha, na província de Luang Namtha, é um projeto modelo para o ecoturismo de base comunitária na Ásia. A reserva protege florestas de montanha e vales fluviais que apresentam uma elevada densidade de grandes mamíferos, como elefantes asiáticos e panteras-nebulosas. Numerosos povos das montanhas, incluindo os Akha e Lanten, vivem dentro ou nos limites do parque e recebem uma fonte de rendimento alternativa através de caminhadas guiadas. Este modelo minimiza significativamente a caça ilegal e a desflorestação. As paisagens do rio Nam Ha também são utilizadas para passeios de caiaque e rafting que levam a áreas de natureza intocada. Cientistas monitorizam aqui as populações de aves e anfíbios raros. O parque demonstra de forma impressionante como a conservação e o desenvolvimento indígena podem unir-se com sucesso.",
      fr: "L'aire protégée nationale de Nam Ha, dans la province de Luang Namtha, est un projet pilote d'écotourisme communautaire en Asie. La réserve protège des forêts de montagne et des vallées fluviales abritant de grands mammifères tels que l'éléphant d'Asie et la panthère nébuleuse. De nombreux peuples montagnards, dont les Akha et les Lanten, vivent dans ou en bordure du parc et bénéficient de revenus alternatifs grâce aux treks guidés. Ce modèle réduit considérablement la chasse et l'abattage illégaux. Les paysages du fleuve Nam Ha sont également prisés pour le kayak et le rafting. Des scientifiques y surveillent les populations d'amphibiens et d'oiseaux rares. Le parc illustre la réussite de l'union entre protection de la nature et développement des populations indigènes.",
    },
