      en: ["Model project for indigenous ecotourism", "Home to many ethnic hill tribes (e.g. Akha)", "Protects mountain rainforests in northern Laos", "Offers well-known jungle trekking routes", "Provides opportunities for rafting on the Nam Ha", "Secures the income of local communities"],
      es: ["Proyecto modelo de ecoturismo indígena", "Hogar de etnias Akha y Lanten", "Protege selvas del norte de Laos", "Rutas famosas de trekking por la selva", "Opciones de rafting en el río Nam Ha", "Asegura ingresos para comunidades locales"],
      pt: ["Projeto modelo para ecoturismo indígena", "Pátria de povos das montanhas (ex: Akha)", "Protege florestas tropicais do norte", "Rotas famosas de trekking na selva", "Possibilidade de rafting no rio Nam Ha", "Garante o rendimento das comunidades"],
      fr: ["Projet modèle d'écotourisme indigène", "Foyer d'ethnies montagnardes (Akha)", "Protège les forêts du nord du Laos", "Routes célèbres de trek en jungle", "Possibilités de rafting sur la Nam Ha", "Sécurise les revenus des communautés"],
