      pt: ["Cultiva vegetais da época sem pesticidas", "Fornece ingredientes frescos a restaurantes", "Especializada em ervas aromáticas laosianas", "Utiliza exclusivamente compostagem natural", "Gere o seu próprio restaurante farm-to-table", "Oferece cursos de autossuficiência urbana"],
